local module = {}
module.__index = module

function module.new(serviceProvider: IServiceProvider)
	local self = setmetatable({}, module)
	self._infos = {}
	self._serviceProvider = serviceProvider

	for k, v in script.Parent.Presets:GetChildren() do
		local value = require(v)
		self:SetInfoProvider(v.Name, value)
	end

	return self
end

function module:GetAllInfos()
	local infos = {}
	for key, provider in self._infos do
		infos[key] = provider(self._serviceProvider)
	end
	return infos
end

function module:GetInfo(key: string)
	return self._infos[key](self._serviceProvider)
end

function module:SetInfoProvider(key: string, provider: (serviceProvider: IServiceProvider) -> any)
	self._infos[key] = provider
end

return module
